package com.company.crm.dashboard;
import com.company.crm.common.ApiResponse;import com.company.crm.security.TenantContext;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1/dashboard") public class DashboardController{
 private final JdbcTemplate db;public DashboardController(JdbcTemplate d){db=d;}
 private boolean all(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN")||x.getAuthority().equals("ROLE_MANAGER"));}
 private Map<String,Object> count(String sql,UUID tenantId,boolean all,String email){return db.queryForMap(sql,tenantId,all,email);}
 @GetMapping("/summary")public ApiResponse<Map<String,Object>> summary(Authentication a){UUID tenantId=TenantContext.requireTenantId();boolean all=all(a);String email=a.getName();Map<String,Object> m=new LinkedHashMap<>();
 m.put("clients",count("select count(*) total from clients c join users u on u.id=c.owner_id where c.tenant_id=? and c.archived_at is null and (? or lower(u.email)=lower(?))",tenantId,all,email));
 m.put("leads",count("select count(*) total,coalesce(sum(estimated_value) filter(where status not in ('WON','LOST')),0) pipeline_value,coalesce(sum(final_value) filter(where status='WON'),0) won_value from leads l join users u on u.id=l.assigned_to where l.tenant_id=? and l.archived_at is null and (? or lower(u.email)=lower(?))",tenantId,all,email));
 m.put("tasks",count("select count(*) filter(where status in ('TODO','IN_PROGRESS')) open,count(*) filter(where due_at<now() and status in ('TODO','IN_PROGRESS')) overdue,count(*) filter(where due_at>=now() and due_at<now()+interval '7 days' and status in ('TODO','IN_PROGRESS')) upcoming from tasks t join users u on u.id=t.assigned_to where t.tenant_id=? and t.archived_at is null and (? or lower(u.email)=lower(?))",tenantId,all,email));
 m.put("projects",db.queryForList("select p.status,count(*) total from projects p join users u on u.id=p.owner_id where p.tenant_id=? and p.archived_at is null and (? or lower(u.email)=lower(?)) group by p.status",tenantId,all,email));
 m.put("recentActivities",db.queryForList("select a.id,a.client_id,a.activity_type,a.subject,a.occurred_at from activities a join clients c on c.id=a.client_id join users u on u.id=c.owner_id where a.tenant_id=? and c.tenant_id=? and (? or lower(u.email)=lower(?)) order by a.occurred_at desc limit 10",tenantId,tenantId,all,email));
 return ApiResponse.ok("Dashboard summary",m);}
 @GetMapping("/leads")public ApiResponse<List<Map<String,Object>>> leads(Authentication a){return ApiResponse.ok("Lead pipeline",db.queryForList("select l.status,count(*) total,coalesce(sum(coalesce(l.final_value,l.estimated_value)),0) value from leads l join users u on u.id=l.assigned_to where l.tenant_id=? and l.archived_at is null and (? or lower(u.email)=lower(?)) group by l.status order by l.status",TenantContext.requireTenantId(),all(a),a.getName()));}
 @GetMapping("/tasks")public ApiResponse<List<Map<String,Object>>> tasks(Authentication a){return ApiResponse.ok("Task report",db.queryForList("select t.status,t.priority,count(*) total from tasks t join users u on u.id=t.assigned_to where t.tenant_id=? and t.archived_at is null and (? or lower(u.email)=lower(?)) group by t.status,t.priority order by t.status,t.priority",TenantContext.requireTenantId(),all(a),a.getName()));}
 @GetMapping("/projects")public ApiResponse<List<Map<String,Object>>> projects(Authentication a){return ApiResponse.ok("Project report",db.queryForList("select p.status,count(*) total,coalesce(sum(p.budget),0) budget from projects p join users u on u.id=p.owner_id where p.tenant_id=? and p.archived_at is null and (? or lower(u.email)=lower(?)) group by p.status order by p.status",TenantContext.requireTenantId(),all(a),a.getName()));}
 @GetMapping("/workload")public ApiResponse<List<Map<String,Object>>> workload(Authentication a){if(!all(a))throw new AccessDeniedException("Manager role required to view team workload");UUID tenantId=TenantContext.requireTenantId();return ApiResponse.ok("Team workload",db.queryForList("""
 select u.id,u.full_name,m.role,
        (select count(*) from tasks t where t.tenant_id=m.tenant_id and t.assigned_to=u.id and t.archived_at is null and t.status in ('TODO','IN_PROGRESS')) open_tasks,
        (select count(*) from tasks t where t.tenant_id=m.tenant_id and t.assigned_to=u.id and t.archived_at is null and t.due_at<now() and t.status in ('TODO','IN_PROGRESS')) overdue_tasks,
        (select count(*) from leads l where l.tenant_id=m.tenant_id and l.assigned_to=u.id and l.archived_at is null and l.status not in ('WON','LOST')) open_leads
 from tenant_memberships m join users u on u.id=m.user_id
 where m.tenant_id=? and m.membership_status='ACTIVE' and u.is_active=true
 order by u.full_name,u.id
 """,tenantId));} @GetMapping("/reports")public ApiResponse<Map<String,Object>> reports(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,Authentication a){LocalDate start=from==null?LocalDate.now().minusDays(30):from;LocalDate end=to==null?LocalDate.now():to;if(end.isBefore(start))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"to must be on/after from");UUID tenantId=TenantContext.requireTenantId();Map<String,Object> m=new LinkedHashMap<>();m.put("from",start);m.put("to",end);m.put("leads",db.queryForList("select status,count(*) total,coalesce(sum(coalesce(final_value,estimated_value)),0) value from leads l join users u on u.id=l.assigned_to where l.tenant_id=? and l.created_at>=? and l.created_at<? and (? or lower(u.email)=lower(?)) group by status",tenantId,start.atStartOfDay(ZoneOffset.UTC).toInstant(),end.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(),all(a),a.getName()));m.put("tasks",db.queryForList("select status,count(*) total from tasks t join users u on u.id=t.assigned_to where t.tenant_id=? and t.created_at>=? and t.created_at<? and (? or lower(u.email)=lower(?)) group by status",tenantId,start.atStartOfDay(ZoneOffset.UTC).toInstant(),end.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(),all(a),a.getName()));return ApiResponse.ok("Date range report",m);}
}


